sys_script.script:
(function executeRule(current, previous) {
    if (!current.student || current.student.nil() || !current.scholarship_program || current.scholarship_program.nil()) return;
    var gr = new GlideRecord("x_2200409_schola_1_scholarship_application");
    gr.addQuery("student", current.student);
    gr.addQuery("scholarship_program", current.scholarship_program);
    gr.addQuery("application_status", "!=", "cancelled");
    if (!current.isNewRecord()) {
        gr.addQuery("sys_id", "!=", current.getUniqueValue());
    }
    gr.query();
    if (gr.hasNext()) {
        gs.addErrorMessage("An active application for this student and scholarship program already exists.");
        current.setAbortAction(true);
    }
})(current, previous);
